/**
 * Minimal hand-rolled YAML-frontmatter parser. Supports exactly the subset
 * used by PAY.md files: top-level `key: value` scalars, `[a, b]` inline
 * arrays, and one level of nesting (`payment:` + indented keys). Anything
 * fancier (block sequences, multi-line strings, anchors) is out of scope on
 * purpose — the registry format is deliberately small.
 */
export type Frontmatter = Record<string, string | string[] | Record<string, string | string[]>>;
/**
 * Split `---`-delimited frontmatter from the markdown body and parse it.
 * Throws on a missing or malformed block.
 */
export declare function parseFrontmatter(content: string): {
    data: Frontmatter;
    body: string;
};
